export const FIGURE_PROFILE_BY_ID = Object.fromEntries(
  FIGURE_PROFILES.map((profile) => [profile.figureId, profile])
);

export function mergeFigureProfile(remoteFigure, profile) {
  if (!remoteFigure && !profile) return null;
  const rich = profile || FIGURE_PROFILE_BY_ID[remoteFigure?.figureId || remoteFigure?.id];
  if (!rich) return remoteFigure;
  return {
    ...(remoteFigure || {}),
    ...rich,
    id: rich.figureId,
    figureId: rich.figureId,
    image_url: rich.media?.find((item) => item.type === "image" && item.url)?.url || null,
    image_source_url: rich.media?.find((item) => item.type === "image" && item.sourceUrl)?.sourceUrl || null,
    image_credit: rich.media?.find((item) => item.type === "image" && item.credit)?.credit || null,
  };
}

export function mergeFigureCatalog(remoteFigures = []) {
  const remoteById = new Map((Array.isArray(remoteFigures) ? remoteFigures : []).map((item) => [item.figureId || item.id, item]));
  const ids = new Set([...remoteById.keys(), ...FIGURE_PROFILES.map((item) => item.figureId)]);
  return [...ids].map((id) => mergeFigureProfile(remoteById.get(id), FIGURE_PROFILE_BY_ID[id]));
}
